with exploded as (select id, plan, element from price_tiers lateral view explode(discounts) li as element) select case when element >= 84 then 'HIGH' else 'LOW' end as element_tier, plan, percentile_approx(element, 0.9) as element_p90, max(element) filter (where plan = 'starter') as starter_max_element, round(sum(element) / nullif(count(case when plan = 'enterprise' then 1 end), 0), 2) as element_per_enterprise from exploded group by element_tier, plan having starter_max_element > 0
